<script setup lang="ts">
import type { BsAdminOperatorForm, BsAdminResourceView, BsPlatformAdministrationCopy } from '../types/platformAdministrationPresentation'
defineProps<{ copy: BsPlatformAdministrationCopy; view: BsAdminResourceView }>()
const form = defineModel<BsAdminOperatorForm>('form', { required: true })
const emit = defineEmits<{ resource: [value: string]; search: [value: string]; status: [value: string]; apply: []; clear: []; refresh: []; page: [delta: number]; memberships: [id: string]; open: [id: string, mode: 'payment' | 'access' | 'subscription' | 'support']; close: []; inspectReceipt: []; submit: [] }>()
function field<K extends keyof BsAdminOperatorForm>(key: K, value: BsAdminOperatorForm[K]) { form.value = { ...form.value, [key]: value } }
</script>
<template>
  <BsStack gap="md">
    <BsText v-if="view.role" role="status">{{ view.role }}</BsText><BsText v-if="view.error" role="alert" tone="danger">{{ view.error }}</BsText><BsText v-if="view.success" role="status">{{ copy.saved }}</BsText>
    <BsInline gap="md" wrap align="end">
      <BsFloatingField :label="copy.view"><BsSelect :label="copy.view" :model-value="view.selected" :disabled="view.pending || view.denied" :options="view.resources" option-label="label" option-value="value" native @update:model-value="emit('resource', String($event))"/></BsFloatingField>
      <BsFloatingField v-if="view.showSearch" :label="copy.search"><BsInput :model-value="view.search" :maxlength="100" :disabled="view.pending || view.denied" @update:model-value="emit('search', String($event ?? ''))" @keyup.enter="emit('apply')"/></BsFloatingField>
      <BsFloatingField v-if="view.statusChoices.length" :label="copy.filter"><BsSelect :label="copy.filter" :model-value="view.status" :disabled="view.pending || view.denied" :options="view.statusChoices" option-label="label" option-value="value" native @update:model-value="emit('status', String($event))"/></BsFloatingField>
      <BsButton v-if="view.showSearch" :disabled="view.pending" @click="emit('apply')">{{ copy.apply }}</BsButton><BsButton v-if="view.clearable" :disabled="view.pending" @click="emit('clear')">{{ copy.clear }}</BsButton><BsButton :disabled="view.pending" @click="emit('refresh')">{{ copy.refresh }}</BsButton>
    </BsInline>
    <BsText v-if="view.scoped" size="sm" tone="muted">{{ copy.scoped }}</BsText><BsText v-if="view.pending" role="status">{{ copy.loading }}</BsText><BsText v-else-if="!view.error && !view.rows.length">{{ copy.empty }}</BsText>
    <BsDataTable v-if="view.rows.length && !view.denied" :value="view.rows" data-key="id" :loading="view.pending" :label="copy.title" :columns="[...view.columns.map(column => ({ ...column, field: `values.${column.key}`, sortField: `values.${column.key}`, sortable: true })), { key: 'actions', header: copy.action }]">
      <template v-for="column in view.columns" :key="column.key" #[`cell-${column.key}`]="{ row }"><BsCodeBlock v-if="column.code" dir="ltr">{{ row.values[column.key] }}</BsCodeBlock><BsText v-else as="span">{{ row.values[column.key] }}</BsText></template>
      <template #cell-actions="{ row }"><BsInline wrap><BsButton v-if="row.memberships" :disabled="view.pending" @click="emit('memberships', row.id)">{{ copy.memberships }}</BsButton><BsButton v-if="row.access" :disabled="view.pending || row.access.disabled" @click="emit('open', row.id, 'access')">{{ row.access.label }}</BsButton><BsButton v-if="row.correction" :disabled="view.pending || row.correction.disabled" @click="emit('open', row.id, 'subscription')">{{ row.correction.label }}</BsButton><BsButton v-if="row.review" :disabled="view.pending" @click="emit('open', row.id, 'payment')">{{ copy.review }}</BsButton><BsButton v-if="row.support" :disabled="view.pending" @click="emit('open', row.id, 'support')">{{ copy.manage }}</BsButton></BsInline></template>
    </BsDataTable>
    <BsInline v-if="view.paginated" gap="md"><BsButton :disabled="view.previousDisabled" @click="emit('page', -50)">{{ copy.previous }}</BsButton><BsButton :disabled="view.nextDisabled" @click="emit('page', 50)">{{ copy.next }}</BsButton></BsInline>
    <BsRecordActionDialog :visible="view.dialog.visible" :title="view.dialog.title" :dirty="view.dialog.dirty" :pending="view.dialog.pending" :error="view.dialog.error" :cancel-label="copy.cancel" @update:visible="value => { if (!value) emit('close') }" @submit="emit('submit')">
      <BsText>{{ view.dialog.recordId }}</BsText><BsText v-if="view.dialog.message" wrap="preserve">{{ view.dialog.message }}</BsText><BsText v-if="view.dialog.currentPlan">{{ copy.currentPlan }}: <BsText as="strong">{{ view.dialog.currentPlan }}</BsText></BsText>
      <template v-if="view.dialog.showReceipt"><BsButton :disabled="view.dialog.pending" @click="emit('inspectReceipt')">{{ copy.inspect }}</BsButton><BsLink v-if="view.dialog.receiptUrl" :to="view.dialog.receiptUrl" target="_blank" rel="noopener noreferrer">{{ copy.openReceipt }}</BsLink></template>
      <BsFloatingField v-if="view.dialog.actionChoices.length" :label="copy.action"><BsSelect :label="copy.action" :model-value="form.action" :disabled="view.dialog.pending" :options="view.dialog.actionChoices" option-label="label" option-value="value" native @update:model-value="field('action', String($event))"/></BsFloatingField>
      <template v-if="view.dialog.showPlan"><BsText v-if="view.dialog.planError" role="alert" tone="danger">{{ view.dialog.planError }}</BsText><BsFloatingField :label="copy.targetPlan"><BsSelect :label="copy.targetPlan" :model-value="form.targetPlan" :disabled="view.dialog.pending || view.dialog.planPending || !!view.dialog.planError" :options="view.dialog.planChoices" option-label="label" option-value="value" native @update:model-value="field('targetPlan', String($event))"/></BsFloatingField></template>
      <template v-if="view.dialog.canSubmit"><BsFloatingField :label="copy.reason"><BsTextarea :model-value="form.reason" required :maxlength="1000" :disabled="view.dialog.pending" @update:model-value="field('reason', String($event ?? ''))"/></BsFloatingField><BsFloatingField v-if="view.dialog.showContext" :label="copy.context"><BsTextarea :model-value="form.context" required :maxlength="1000" :disabled="view.dialog.pending" @update:model-value="field('context', String($event ?? ''))"/></BsFloatingField></template>
      <template #actions="{ close }"><BsButton :disabled="view.dialog.pending" @click="close">{{ copy.cancel }}</BsButton><BsButton v-if="view.dialog.canSubmit" type="submit" variant="primary" :pending="view.dialog.pending" :disabled="!form.reason.trim() || (view.dialog.showContext && !form.context.trim())">{{ copy.submit }}</BsButton></template>
    </BsRecordActionDialog>
  </BsStack>
</template>
